import * as T from './vendor/three.module.js';
import {ARTIFACTS} from './engine.mjs';
const TAU=Math.PI*2;
const standard=(c,r=.35,m=0)=>new T.MeshStandardMaterial({color:c,roughness:r,metalness:m});
function mesh(g,m,x=0,y=0,z=0){let o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;return o;}
function ceramicTexture(blue=false){const c=document.createElement('canvas');c.width=c.height=1024;const x=c.getContext('2d');x.fillStyle=blue?'#d8ded2':'#91b9ad';x.fillRect(0,0,1024,1024);for(let i=0;i<19000;i++){let a=Math.random()*1024,b=Math.random()*1024;x.fillStyle=`rgba(${Math.random()>.5?'235,241,210':'40,80,62'},${Math.random()*.065})`;x.fillRect(a,b,2,2);}x.lineWidth=.6;for(let i=0;i<95;i++){let a=Math.random()*1024,b=Math.random()*1024;x.strokeStyle=`rgba(50,76,55,${Math.random()*.12})`;x.beginPath();x.moveTo(a,b);for(let k=0;k<5;k++){a+=(Math.random()-.5)*65;b+=Math.random()*35;x.lineTo(a,b);}x.stroke();}if(blue){x.strokeStyle='#314d78';x.lineWidth=7;for(let y of [80,105,865,890]){x.beginPath();x.moveTo(0,y);x.lineTo(1024,y);x.stroke();}for(let j=0;j<8;j++){let cx=j*145+10,cy=470+Math.sin(j*2)*75;x.strokeStyle='#365882';x.lineWidth=4;x.beginPath();x.moveTo(cx-65,730);x.bezierCurveTo(cx+120,520,cx-140,380,cx+75,270);x.stroke();for(let k=0;k<8;k++){let a=k*Math.PI/4;x.beginPath();x.ellipse(cx+Math.cos(a)*31,cy+Math.sin(a)*31,30,12,a,0,TAU);x.stroke();}x.beginPath();x.arc(cx,cy,12,0,TAU);x.stroke();for(let k=0;k<4;k++){let yy=300+k*100,xx=cx+Math.sin(k*2)*34;x.beginPath();x.ellipse(xx,yy,32,9,-.6+k*.5,0,TAU);x.stroke();}}}const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;return tx;}
let greenMap,blueMap;
function lathe(points,mat){return mesh(new T.LatheGeometry(new T.SplineCurve(points.map(p=>new T.Vector2(...p))).getPoints(140),96),mat);}
function torus(r,t,mat,y=0,rx=Math.PI/2){let o=mesh(new T.TorusGeometry(r,t,12,80),mat,0,y);o.rotation.x=rx;return o;}
export function createArtifact(art){const d=ARTIFACTS[art];const g=new T.Group();let material;
 if(['vase','bluevase','bowl','jade'].includes(d.type)){let map=d.type==='bluevase'?(blueMap||(blueMap=ceramicTexture(true))):(greenMap||(greenMap=ceramicTexture()));material=new T.MeshPhysicalMaterial({color:d.type==='jade'?0xd0debd:0xffffff,map:d.type==='jade'?null:map,roughness:d.type==='jade'?.2:.23,metalness:.08,clearcoat:1,clearcoatRoughness:.15});}else material=standard(d.color,d.type==='teapot'?.76:.38,d.type==='teapot'?.03:.72);
 const gold=standard(0xbca16c,.3,.8),dark=standard(0x342d1f,.8,.4);
 if(d.type==='vase'||d.type==='bluevase'||d.type==='jade'){
 const p=d.type==='bluevase'?[[.3,0],[.42,.05],[.45,.2],[.47,.65],[.58,1.25],[.73,1.8],[.73,2],[.55,2.23],[.26,2.42],[.25,2.66],[.29,2.72],[.25,2.75],[.20,2.70],[.2,2.46]]:d.type==='jade'?[[.37,0],[.5,.1],[.62,.5],[.62,1.15],[.47,1.6],[.24,1.84],[.24,2.27],[.31,2.4],[.3,2.44],[.23,2.43],[.19,2.32],[.19,1.87]]:[[.37,0],[.45,.06],[.46,.18],[.55,.3],[.76,.7],[.82,1.14],[.74,1.47],[.55,1.68],[.29,1.84],[.235,2.07],[.235,2.58],[.29,2.66],[.29,2.73],[.235,2.77],[.205,2.7],[.19,2.58],[.19,2.08]];
 g.add(lathe(p,material));g.add(torus(p[0][0],.016,material,.035));if(d.type==='vase'){for(let y of [.45,.51,.57]){let r=.61+(y-.45)*.5;g.add(torus(r+.008,.012,material,y));}for(let y of [1.57,1.62,1.67]){let r=.65-(y-1.57)*1.8;g.add(torus(r+.008,.012,material,y));}for(let y of [2.19,2.26,2.33])g.add(torus(.238,.017,material,y));}if(d.type==='jade'){for(let s of [-1,1]){let t=torus(.22,.045,material,1.91,0);t.position.x=s*.4;g.add(t);let ring=torus(.2,.028,material,1.6,0);ring.position.x=s*.55;g.add(ring);}for(let y of [.12,1.13])g.add(torus(y===.12?.5:.62,.025,material,y));}
 }else if(d.type==='incense'){g.add(lathe([[.25,.34],[.5,.36],[.7,.52],[.79,.86],[.76,1.1],[.7,1.25],[.71,1.35],[.63,1.38],[.61,1.28],[.65,1.17],[.7,1.07]],material));g.add(torus(.7,.035,gold,1.32));g.add(torus(.57,.026,gold,.43));for(let i=0;i<3;i++){let a=i*TAU/3;let foot=mesh(new T.CylinderGeometry(.13,.075,.47,20),material,Math.cos(a)*.48,.2,Math.sin(a)*.48);foot.rotation.z=-Math.cos(a)*.18;g.add(foot);}for(let s of [-1,1]){let h=torus(.24,.063,material,1.32,0);h.position.x=s*.85;g.add(h);let n=mesh(new T.SphereGeometry(.145,20,12),gold,s*.68,1.17);n.scale.set(1,.7,1);g.add(n);}g.scale.setScalar(1.28);
 }else if(d.type==='teapot'){g.add(lathe([[.33,.06],[.58,.16],[.74,.49],[.66,.8],[.47,.94],[.4,.97]],material));g.add(lathe([[0,1.04],[.22,1.03],[.39,.97],[.47,.96]],material));g.add(mesh(new T.SphereGeometry(.105,24,16),material,0,1.12));let h=torus(.39,.075,material,.61,0);h.position.x=.77;g.add(h);let curve=new T.CatmullRomCurve3([new T.Vector3(-.5,.4,0),new T.Vector3(-.83,.53,0),new T.Vector3(-1,.8,0),new T.Vector3(-1.18,1.03,0)]);g.add(mesh(new T.TubeGeometry(curve,30,.135,16,false),material));g.add(torus(.39,.019,material,.08));g.scale.setScalar(1.5);
 }else if(d.type==='bowl'){g.add(lathe([[.31,.02],[.4,.08],[.4,.18],[.67,.35],[.87,.65],[1,.96],[.99,1.02],[.95,1.03],[.92,.93],[.79,.62],[.61,.38],[.35,.23],[0,.22]],material));for(let i=0;i<16;i++){const a=i*TAU/16;let leaf=mesh(new T.SphereGeometry(.08,12,10),material,Math.sin(a)*.77,.57,Math.cos(a)*.77);leaf.scale.set(.4,3.7,1);leaf.rotation.z=-Math.sin(a)*.4;g.add(leaf);}g.scale.setScalar(1.45);
 }else if(d.type==='mirror'){let m=mesh(new T.CylinderGeometry(1,1,.1,96),material,0,1.25);m.rotation.x=Math.PI/2;g.add(m);for(let r of [.95,.82,.35]){let ring=torus(r,.025,gold,1.25,0);ring.position.z=.065;g.add(ring);}g.add(mesh(new T.SphereGeometry(.17,24,16),material,0,1.25,.15));for(let i=0;i<20;i++){let a=i*TAU/20;let o=mesh(new T.SphereGeometry(.07,12,8),material,Math.cos(a)*.69,1.25+Math.sin(a)*.69,.1);o.scale.set(1,1,.5);g.add(o);let o2=mesh(new T.TorusGeometry(.085,.016,6,16),gold,Math.cos(a)*.53,1.25+Math.sin(a)*.53,.105);g.add(o2);}g.add(mesh(new T.BoxGeometry(.8,.08,.55),dark,0,.03));g.add(mesh(new T.BoxGeometry(.09,1.5,.09),dark,0,.75,-.12));
 }else if(d.type==='clock'){g.add(mesh(new T.BoxGeometry(1.35,1.9,.65),gold,0,1.12));g.add(mesh(new T.BoxGeometry(1.17,1.72,.04),dark,0,1.12,.35));let face=mesh(new T.CircleGeometry(.5,64),standard(0xddd9be,.7),0,1.25,.38);g.add(face);for(let i=0;i<12;i++){let a=i*TAU/12;let mark=mesh(new T.BoxGeometry(.025,.065,.014),dark,Math.sin(a)*.41,1.25+Math.cos(a)*.41,.4);mark.rotation.z=-a;g.add(mark);}let hand=mesh(new T.BoxGeometry(.025,.38,.02),dark,0,1.41,.415);hand.rotation.z=-.5;g.add(hand);let hand2=mesh(new T.BoxGeometry(.025,.28,.02),dark,.10,1.22,.425);hand2.rotation.z=1.3;g.add(hand2);let h=torus(.24,.037,gold,2.24,0);g.add(h);g.add(mesh(new T.BoxGeometry(1.5,.1,.8),gold,0,.15));g.add(mesh(new T.BoxGeometry(1.48,.1,.77),gold,0,2.1));}
 g.userData.material=material;g.rotation.y=.35;return g;
}
export class Viewer{
 constructor(){this.ready=false;this.auto=true;this.uv=false;this.zoom=7.2;this.angle=0;this.tilt=2.25;this.last=0;this.model=null;this.currentId=-1;this.thumbs={};this.reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;try{this.renderer=new T.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true,powerPreference:'high-performance'});}catch(e){this.error=true;return;}const r=this.renderer;r.setPixelRatio(Math.min(devicePixelRatio,1.75));r.shadowMap.enabled=true;r.shadowMap.type=T.PCFSoftShadowMap;r.outputColorSpace=T.SRGBColorSpace;r.toneMapping=T.ACESFilmicToneMapping;r.toneMappingExposure=1.25;r.domElement.id='scene';r.domElement.setAttribute('aria-label','3D 藏品展台，拖动旋转，滚轮缩放');r.domElement.setAttribute('role','img');r.domElement.tabIndex=0;this.scene=new T.Scene();this.scene.background=new T.Color(0x1a211b);this.scene.fog=new T.FogExp2(0x161d16,.065);this.camera=new T.PerspectiveCamera(35,1,.1,60);this.room=new T.Group();this.scene.add(this.room);this.scene.add(new T.HemisphereLight(0xdbe5d2,0x242e19,2));const key=new T.SpotLight(0xffe0aa,75,20,.5,.85,1.5);key.position.set(2.4,6,3.5);key.target.position.set(0,.8,0);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.bias=-.00015;this.scene.add(key,key.target);this.key=key;const rim=new T.DirectionalLight(0xc5efe0,3.2);rim.position.set(-4,3,-2);this.scene.add(rim);const fill=new T.PointLight(0xd2cf9b,13,12);fill.position.set(-3,2,3);this.scene.add(fill);
 const env=new T.Scene();env.background=new T.Color(0x41483c);for(let i=0;i<3;i++){let p=mesh(new T.PlaneGeometry(4,6),new T.MeshBasicMaterial({color:i===0?0xffffed:0x8da59d}),i===0?3:-4,2,i===2?-3:1);p.lookAt(0,0,0);env.add(p);}let pmrem=new T.PMREMGenerator(r);this.envMap=pmrem.fromScene(env,.02).texture;this.scene.environment=this.envMap;pmrem.dispose();this.buildRoom();this.bind();this.ready=true;this.animate=this.animate.bind(this);requestAnimationFrame(this.animate);}
 buildRoom(){const wood=standard(0x27251b,.8),edge=standard(0x746047,.65,.25),back=standard(0x1c251b,.9);this.room.add(mesh(new T.PlaneGeometry(40,40),standard(0x252d22,.72),0,-.91));this.room.children[this.room.children.length-1].rotation.x=-Math.PI/2;this.room.add(mesh(new T.BoxGeometry(18,9,.2),back,0,2,-4.2));for(let x of [-5.3,-2.9,2.9,5.3]){this.room.add(mesh(new T.BoxGeometry(.17,7,.4),wood,x,2,-3.7));this.room.add(mesh(new T.BoxGeometry(.025,7,.43),edge,x+.1,2,-3.69));}for(let side of [-1,1]){for(let y of [-.05,1.5,3.05,4.6])this.room.add(mesh(new T.BoxGeometry(2.3,.09,.76),wood,side*4.1,y,-3.65));for(let j=0;j<3;j++){let pot=lathe([[.2,0],[.35,.2],[.34,.5],[.15,.67],[.13,.88]],standard(j===1?0x737657:0x665133,.72,.3));pot.position.set(side*(3.65+(j%2)*.7),1.55+(j===2?1.55:0),-3.4);pot.scale.setScalar(j===1?.65:1.05);this.room.add(pot);}let glow=new T.PointLight(0xe0bb77,3,4);glow.position.set(side*4,3,-3);this.scene.add(glow);}let panel=mesh(new T.BoxGeometry(3.3,4.5,.1),standard(0x293425,.95),0,2.4,-4);this.room.add(panel);for(let x of [-1.65,1.65])this.room.add(mesh(new T.BoxGeometry(.025,4.5,.04),edge,x,2.4,-3.92));for(let y of [.16,4.65])this.room.add(mesh(new T.BoxGeometry(3.3,.025,.04),edge,0,y,-3.92));
 const pedestal=mesh(new T.CylinderGeometry(1.3,1.37,.67,96),standard(0x24291f,.67,.12),0,-.55);this.room.add(pedestal);this.room.add(mesh(new T.CylinderGeometry(1.43,1.43,.11,96),standard(0x4c4b39,.5,.2),0,-.16));this.room.add(mesh(new T.CylinderGeometry(1.44,1.44,.02,96),standard(0x97865a,.45,.45),0,-.105));this.room.add(mesh(new T.CylinderGeometry(1.4,1.4,.035,96),standard(0x373c2c,.78),0,-.079));this.room.add(torus(1.365,.013,edge,-.79));
 const dust=new T.BufferGeometry();let arr=new Float32Array(100*3);for(let i=0;i<arr.length;i++)arr[i]=(Math.random()-.5)*11;dust.setAttribute('position',new T.BufferAttribute(arr,3));this.dust=new T.Points(dust,new T.PointsMaterial({color:0xd8d3b2,size:.014,transparent:true,opacity:.32,depthWrite:false}));this.scene.add(this.dust);}
 mount(el,art){if(this.error){el.innerHTML='<div class="view-warning">当前设备未启用 WebGL。<br>仍可使用鉴宝报告与完整经营玩法。</div>';return;}el.prepend(this.renderer.domElement);if(this.currentId!==art)this.setArtifact(art);this.resize();if(this.observer)this.observer.disconnect();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(el);}
 setArtifact(art){if(this.model)this.disposeModel(this.model);this.model=createArtifact(art);this.scene.add(this.model);this.currentId=art;this.uv=false;this.key.color.setHex(0xffe0aa);this.zoom=7.2;this.tilt=2.25;this.angle=0;}
 disposeModel(model){this.scene.remove(model);model.traverse(o=>{if(o.isMesh){o.geometry.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}});}
 resize(){if(!this.renderer.domElement.parentElement)return;const rect=this.renderer.domElement.parentElement.getBoundingClientRect();if(rect.width<2||rect.height<2)return;this.renderer.setSize(rect.width,rect.height,false);this.camera.aspect=rect.width/rect.height;this.camera.updateProjectionMatrix();}
 bind(){let drag=false,lx=0,ly=0;const c=this.renderer.domElement;c.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;c.setPointerCapture(e.pointerId);});c.addEventListener('pointermove',e=>{if(drag&&this.model){this.model.rotation.y+=(e.clientX-lx)*.012;this.tilt=Math.max(.35,Math.min(5.5,this.tilt+(e.clientY-ly)*.016));lx=e.clientX;ly=e.clientY;}});c.addEventListener('keydown',e=>{if(!this.model)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')this.model.rotation.y-=.15;if(e.key==='ArrowRight')this.model.rotation.y+=.15;if(e.key==='ArrowUp')this.tilt=Math.min(5.5,this.tilt+.2);if(e.key==='ArrowDown')this.tilt=Math.max(.35,this.tilt-.2);if(e.key==='+')this.zoom=Math.max(4.2,this.zoom-.4);if(e.key==='-')this.zoom=Math.min(10,this.zoom+.4);}});c.addEventListener('pointerup',()=>drag=false);c.addEventListener('pointercancel',()=>drag=false);c.addEventListener('wheel',e=>{e.preventDefault();this.zoom=Math.max(4.2,Math.min(10,this.zoom+e.deltaY*.004));},{passive:false});}
 toggleUV(){this.uv=!this.uv;this.key.color.setHex(this.uv?0x9966ff:0xffe0aa);if(this.model?.userData.material.emissive){this.model.userData.material.emissive.setHex(this.uv?0x1e0640:0);this.model.userData.material.emissiveIntensity=.25;}return this.uv;}
 reset(){this.zoom=7.2;this.tilt=2.25;if(this.model)this.model.rotation.y=.35;}
 animate(time){requestAnimationFrame(this.animate);if(!this.renderer.domElement.isConnected||document.hidden)return;let delta=Math.min((time-this.last)/1000,.05);this.last=time;if(this.auto&&!this.reduce&&this.model)this.model.rotation.y+=delta*.10;this.dust.rotation.y+=delta*.012;this.camera.position.set(0,this.tilt,this.zoom);this.camera.lookAt(0,1.13,0);this.renderer.render(this.scene,this.camera);}
 thumbnail(art){if(this.thumbs[art])return this.thumbs[art];if(!this.ready)return '';const m=createArtifact(art),sc=new T.Scene();sc.background=new T.Color(0x252e24);sc.environment=this.envMap;sc.add(new T.HemisphereLight(0xffffe9,0x26311f,3));let light=new T.DirectionalLight(0xffffed,4);light.position.set(3,5,4);sc.add(light);sc.add(m);m.rotation.y=.55;let cam=new T.PerspectiveCamera(34,1,.1,20);cam.position.set(0,1.7,5.8);cam.lookAt(0,1.25,0);let prev=this.renderer.getSize(new T.Vector2());let ratio=this.renderer.getPixelRatio();this.renderer.setPixelRatio(1);this.renderer.setSize(160,160,false);this.renderer.render(sc,cam);const url=this.renderer.domElement.toDataURL('image/png');this.renderer.setPixelRatio(ratio);this.renderer.setSize(prev.x,prev.y,false);this.disposeModel(m);this.thumbs[art]=url;return url;}
}
